using Astrea.BattleActions;
using Kittehface;
using LittleLeo;
using LittleLeo.Events;
using LittleLeo.Variables;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "GameController", menuName = "Data/Handlers/GameController", order = 0)]
public class GameController : ScriptableObject
{
	public enum ActivityType
	{
		None,
		MainActivity,
		DailyRun
	}

	[Header("Assets")]
	[SerializeField]
	private MapHandler mapHandler;

	[SerializeField]
	private PlayerDiceInventoryData dicePool;

	[SerializeField]
	private PlayerDiceInventoryData diceBag;

	[SerializeField]
	private PlayerDiceInventoryData discard;

	[SerializeField]
	private PlayerDiceInventoryData oncePerBattleDice;

	[SerializeField]
	private PlayerCurrentOmens currentOmens;

	[SerializeField]
	private CurrentCompanions currentCompanions;

	[SerializeField]
	private PlayerCurrentRunes playerCurrentRunes;

	[SerializeField]
	private SaveSystem saveSystem;

	[SerializeField]
	private BoolReference shuffleOmenActiveBoolReference;

	[SerializeField]
	private OmensListsList omensListsList;

	[SerializeField]
	private DicesRewardsListsList dicesRewardsListsList;

	[SerializeField]
	private PlayerScoreXPData playerScoreXPData;

	[SerializeField]
	private RepeatedEventsList repeatedEventsList;

	[Header("Events")]
	[SerializeField]
	private VoidEvent OnTurnContinueGameButtonOn;

	[SerializeField]
	private VoidEvent OnStopCurrentBGM;

	[Header("Demo")]
	[SerializeField]
	private bool isDemo;

	[SerializeField]
	private Character cellariusCharacter;

	[SerializeField]
	private bool isEventDemo;

	[SerializeField]
	[ShowIf("isEventDemo")]
	private bool isEventDemoCellariusStartsUnlocked;

	[SerializeField]
	[ShowIf("isEventDemo")]
	private bool isEventDemoWithDebug;

	[SerializeField]
	private bool isDemoWithTimer;

	[Header("Release Build with Debug")]
	[SerializeField]
	private bool isReleaseBuildWithDebug;

	[Header("Debug")]
	[SerializeField]
	private BattleCorruptedAnimals currentBattleCorruptedAnimals;

	[SerializeField]
	private bool mobileInputEditorDebugMode;

	public bool isNewRun;

	private bool isDailyRun;

	private bool isModEnabled;

	public ActivityType activityType;

	public bool launchingActivity;

	public bool IsDemo => isDemo;

	public bool IsEventDemo => isEventDemo;

	public bool IsEventDemoCellariusStartsUnlocked => isEventDemoCellariusStartsUnlocked;

	public bool IsEventDemoWithDebug => isEventDemoWithDebug;

	public bool IsDemoWithTimer => isDemoWithTimer;

	public bool IsReleaseBuildWithDebug => isReleaseBuildWithDebug;

	public bool MobileInputEditorDebugMode => mobileInputEditorDebugMode;

	public bool IsNewRun => isNewRun;

	public bool IsDailyRun => isDailyRun;

	public bool IsModEnabled => isModEnabled;

	public void SetDemo(bool value)
	{
		isDemo = value;
	}

	public void DisableIsEventDemo()
	{
		isEventDemo = false;
		isEventDemoCellariusStartsUnlocked = false;
		isEventDemoWithDebug = false;
	}

	public void DisableIsDemoWithTimer()
	{
		isDemoWithTimer = false;
	}

	public void SetIsReleaseBuildWithDebug(bool value)
	{
		isReleaseBuildWithDebug = value;
	}

	public void SetMobileInputEditorDebugMode(bool value)
	{
		mobileInputEditorDebugMode = value;
	}

	public void SetIsNewRun(bool value)
	{
		isNewRun = value;
	}

	public void SetIsDailyRun(bool value)
	{
		isDailyRun = value;
	}

	public void SetModEnabled(bool value)
	{
		isModEnabled = value;
	}

	public void NewGame()
	{
		GoToBattleScene(isNewRun: true);
		StoreBackup();
	}

	public void ResetModsInBattle()
	{
		string characterName = ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterName;
		if (saveSystem.HasModVirtuesSetBattleSaveKey(characterName))
		{
			saveSystem.DeleteModVirtuesSetBattleSaveKey(characterName);
		}
		if (saveSystem.HasModStarterDiceSetBattleSaveKey(characterName))
		{
			saveSystem.DeleteModStarterDiceSetBattleSaveKey(characterName);
		}
		if (saveSystem.HasModBlessingsSetBattleSaveKey(characterName))
		{
			saveSystem.DeleteModBlessingsSetBattleSaveKey(characterName);
		}
		if (saveSystem.HasModSentinelsSetBattleSaveKey(characterName))
		{
			saveSystem.DeleteModSentinelsSetBattleSaveKey(characterName);
		}
	}

	public void SaveSetModSelection()
	{
		SaveStarterDiceSetModSelection();
		SaveVirtueSetModSelection();
		SaveBlessingsSetModSelection();
		SaveSentinelsSetModSelection();
	}

	private void SaveStarterDiceSetModSelection()
	{
		string characterName = ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterName;
		if (saveSystem.HasModStarterDiceSetSelectionSaveKey(characterName))
		{
			SaveSystem.ModStarterDiceSetSave value = saveSystem.LoadModStarterDiceSetSelection(characterName);
			saveSystem.SaveModStarterDiceSetBattle(value, characterName);
		}
	}

	private void SaveVirtueSetModSelection()
	{
		string characterName = ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterName;
		if (saveSystem.HasModVirtuesSetSelectionSaveKey(characterName))
		{
			SaveSystem.ModVirtuesSetSave value = saveSystem.LoadModVirtuesSetSelection(characterName);
			saveSystem.SaveModVirtuesSetBattle(value, characterName);
		}
	}

	private void SaveBlessingsSetModSelection()
	{
		string characterName = ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterName;
		if (saveSystem.HasModBlessingsSetSelectionSaveKey(characterName))
		{
			SaveSystem.ModBlessingsSetSave value = saveSystem.LoadModBlessingsSetSelection(characterName);
			saveSystem.SaveModBlessingsSetBattle(value, characterName);
		}
	}

	private void SaveSentinelsSetModSelection()
	{
		string characterName = ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterName;
		if (saveSystem.HasModSentinelsSetSelectionSaveKey(characterName))
		{
			SaveSystem.ModSentinelsSetSave value = saveSystem.LoadModSentinelsSetSelection(characterName);
			saveSystem.SaveModSentinelsSetBattle(value, characterName);
		}
	}

	public void NewGameAfterTutorialEventDemo()
	{
		GoToBattleScene(isNewRun: true);
	}

	public void CheckTutorial()
	{
		if ((!isDemo || !isEventDemo || !(ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter == cellariusCharacter)) && !saveSystem.PlayerAlreadyPlayedTutorial())
		{
			SetIsOnTutorial();
		}
	}

	[Button(null)]
	private void SetIsOnTutorial()
	{
		mapHandler.SetOverrideSetBattleScene(value: true);
		mapHandler.SetTutorialSetup();
		mapHandler.MapPlayerTracker.CurrentAreaLevelIndex = 0;
		mapHandler.MapPlayerTracker.CurrentNodeIndex = 0;
		saveSystem.SaveOnBattle(value: true);
	}

	[Button(null)]
	public void ContinueGame()
	{
		LoadRun();
		GoToBattleScene(isNewRun: false);
		OnStopCurrentBGM.Raise();
		StoreBackup();
	}

	private void LoadRun()
	{
		discard.OnResetToStartRunState();
		diceBag.OnResetToStartRunState();
		saveSystem.LoadRunData();
	}

	public void InitializeAssetsContinueBattleSceneInitializer()
	{
		omensListsList.PopulateCurrentCharacterUnlockedOmenTierOmenDatas(isDailyRun);
		dicesRewardsListsList.PopulateAnyAndCurrentCharacterUnlockedDiceTierDiceList(isDailyRun);
		mapHandler.PopulateMap();
	}

	public void SetupContinueButton()
	{
		if (saveSystem.HasRunSeedKey() && saveSystem.PlayerAlreadyPlayedTutorial())
		{
			OnTurnContinueGameButtonOn.Raise();
		}
	}

	public void TryAgain()
	{
		if (isDailyRun)
		{
			ReferenceSingleton<AssetsReference>.Instance.DailyRunHandler.SetupDailyRun(randomizeSeedDebug: false);
		}
		GoToBattleScene(isNewRun: true);
		StoreBackup();
	}

	public void GoToIntroCutscene()
	{
		if (GameScenesUtils.IsBattleScene())
		{
			SaveBattleSceneAndGoToNextScene(2);
		}
		else
		{
			TransitionCanvas.Instance.FadeTransitionLoadSceneAsync(2);
		}
	}

	public void GoToMainMenu()
	{
		if (GameScenesUtils.IsBattleScene())
		{
			SaveBattleSceneAndGoToNextScene(3);
		}
		else
		{
			TransitionCanvas.Instance.FadeTransitionLoadSceneAsync(3);
		}
	}

	private void SaveBattleSceneAndGoToNextScene(int nextScene)
	{
		InvokeAlternatives.InvokeAfterFrame(ReferenceSingleton<CoroutineHandler>.Instance, delegate
		{
			SettingsPanel.alreadyInitialized = false;
			mapHandler.SetOverrideSetBattleScene(value: false);
			currentBattleCorruptedAnimals.DebugBattle = false;
			ReferenceSingleton<SFXHandler>.Instance.StopAllSFX();
			ReferenceSingleton<InputManager>.Instance.SetPauseGame(value: false);
			BackgroundMusic.instance.OnStopCurrentBGM();
			BackgroundMusic.instance.GameResume();
			TransitionCanvas.Instance.FadeTransitionLoadSceneAsync(nextScene);
			StoreBackup();
		});
	}

	private void GoToBattleScene(bool isNewRun)
	{
		SetIsNewRun(isNewRun);
		TransitionCanvas.Instance.FadeTransitionLoadSceneAsync(4);
		UpdatePS5ActivityStates();
	}

	[Button(null)]
	public void ResetAssetsToDefaultState()
	{
		if (!isDailyRun)
		{
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunStats.GenerateSeed();
		}
		mapHandler.OnResetToStartRunState();
		mapHandler.SetOverrideSetBattleScene(value: false);
		repeatedEventsList.OnResetToStartRunState();
		saveSystem.SaveRepeatedEvents(saveAndStoreCache: false);
		ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.OnResetToStartRunStateBeforeMapPopulate();
		saveSystem.SaveHiddenAnomalyLevelSecondBossPackageName();
		saveSystem.SaveHiddenAnomalyLevelFirstBossDefeatedStartBattleOnSecondBoss();
		mapHandler.PopulateMap();
		saveSystem.SaveOnBattle(value: false);
		ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.OnResetToStartRunState();
		saveSystem.SaveAstreaFirstPhaseDefeatedStartBattleOnAstreaSecondPhase();
		saveSystem.ResetActiveStarIndexIntReference();
		ReferenceSingleton<AssetsReference>.Instance.PlayerRunStats.OnResetToStartRunState();
		if (!isDailyRun)
		{
			dicePool.OnResetToStartRunState();
		}
		diceBag.OnResetToStartRunState();
		discard.OnResetToStartRunState();
		oncePerBattleDice.OnResetToStartRunState();
		currentOmens.OnResetToStartRunState();
		currentCompanions.OnResetToStartRunState();
		if (!isDailyRun)
		{
			playerCurrentRunes.OnResetToStartRunState();
		}
		playerScoreXPData.OnResetToStartRunState();
		shuffleOmenActiveBoolReference.SetValue(value: false);
		omensListsList.PopulateCurrentCharacterUnlockedOmenTierOmenDatas();
		if (!isDailyRun)
		{
			dicesRewardsListsList.PopulateAnyAndCurrentCharacterUnlockedDiceTierDiceList();
		}
		saveSystem.SaveRunData();
	}

	private void StoreBackup()
	{
		InvokeAlternatives.InvokeAfterFrame(ReferenceSingleton<CoroutineHandler>.Instance, delegate
		{
			saveSystem.StoreBackupFile();
		});
	}

	private void UpdatePS5ActivityStates()
	{
		UpdateMainActivity();
		UpdateDailyRunActivity();
		launchingActivity = false;
		activityType = ActivityType.None;
	}

	public void UpdateMainActivity()
	{
		bool flag = ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacterProgression.AstreaLevelsDefeated.Count > 0;
		PS5ActivitiesSinglePlayerStateManager.ActivityState activityState = PS5ActivitiesSinglePlayerStateManager.ActivityState.None;
		activityState = ((!flag) ? PS5ActivitiesSinglePlayerStateManager.ActivityState.Running : PS5ActivitiesSinglePlayerStateManager.ActivityState.Ended);
		PS5ActivitiesSinglePlayerStateManager.SetActivityState("Astrea", !flag, activityState);
	}

	public void UpdateDailyRunActivity()
	{
		bool flag = ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacterProgression.AstreaLevelsDefeated.Count > 0;
		PS5ActivitiesSinglePlayerStateManager.ActivityState activityState = PS5ActivitiesSinglePlayerStateManager.ActivityState.None;
		if (flag && isDailyRun)
		{
			activityState = PS5ActivitiesSinglePlayerStateManager.ActivityState.Running;
		}
		else if (PS5ActivitiesSinglePlayerStateManager.GetActivityState("DailyRun") != PS5ActivitiesSinglePlayerStateManager.ActivityState.Running)
		{
			activityState = PS5ActivitiesSinglePlayerStateManager.ActivityState.NotStarted;
		}
		PS5ActivitiesSinglePlayerStateManager.SetActivityState("DailyRun", flag, activityState);
	}
}
